protocol InventoryGateway { func checkStock(sku: String) async throws -> Stock }

actor AmqpInventoryGateway: InventoryGateway {   // domain-facing contract
    private var pending: [String: CheckedContinuation<Stock, Error>] = [:]
    func checkStock(sku: String) async throws -> Stock {
        try await withCheckedThrowingContinuation { cont in
            let id = UUID().uuidString
            pending[id] = cont                 // the inbound callback resumes it
            send(Request(sku: sku, correlationId: id, replyTo: inbox))
        }
    }
}
